CREATE EXTENSION IF NOT EXISTS vector; CREATE TYPE "DocumentStatus" AS ENUM ('PENDING_UPLOAD','UPLOADED','QUEUED','PROCESSING','READY','FAILED','DELETED');
CREATE TABLE "Tenant"("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL);CREATE TABLE "ApiKey"("id" TEXT PRIMARY KEY,"tenantId" TEXT NOT NULL REFERENCES "Tenant"("id") ON DELETE CASCADE,"name" TEXT NOT NULL,"keyHash" TEXT NOT NULL UNIQUE,"lastUsedAt" TIMESTAMP(3));CREATE INDEX "ApiKey_tenantId_idx" ON "ApiKey"("tenantId");
CREATE TABLE "Document"("id" TEXT PRIMARY KEY,"tenantId" TEXT NOT NULL REFERENCES "Tenant"("id") ON DELETE CASCADE,"fileName" TEXT NOT NULL,"mediaType" TEXT NOT NULL,"bytes" INTEGER NOT NULL,"checksum" TEXT NOT NULL,"status" "DocumentStatus" NOT NULL DEFAULT 'PENDING_UPLOAD',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE INDEX "Document_tenantId_status_createdAt_idx" ON "Document"("tenantId","status","createdAt");
CREATE TABLE "DocumentVersion"("id" TEXT PRIMARY KEY,"documentId" TEXT NOT NULL REFERENCES "Document"("id") ON DELETE CASCADE,"version" INTEGER NOT NULL,"objectKey" TEXT NOT NULL,"pageCount" INTEGER,UNIQUE("documentId","version"));CREATE TABLE "Job"("id" TEXT PRIMARY KEY,"tenantId" TEXT NOT NULL REFERENCES "Tenant"("id") ON DELETE CASCADE,"versionId" TEXT NOT NULL REFERENCES "DocumentVersion"("id") ON DELETE CASCADE,"type" TEXT NOT NULL,"status" TEXT NOT NULL,"attempt" INTEGER NOT NULL DEFAULT 0,"errorCode" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE INDEX "Job_tenantId_status_createdAt_idx" ON "Job"("tenantId","status","createdAt");

